UPDATE shelter_goods
SET number_now = #{numberNow}
WHERE goods_id = #{goodsId};

UPDATE shelter_goods
SET number_req = #{numberReq}
WHERE goods_id = #{goodsId};

UPDATE shelter_goods SET number_req = number_req + CASE goods_id
WHEN #{item.goodsId} THEN #{item.numberReq}
ELSE 0 END WHERE goods_id IN
#{item.goodsId}
